import{_ as o,C as s,o as r,c as n,j as t,a as d,E as i,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const g=JSON.parse('{"title":"Metrics for Prometheus and Grafana","description":"","frontmatter":{},"headers":[],"relativePath":"install/metrics.md","filePath":"install/metrics.md"}'),l={name:"install/metrics.md"};function h(p,e,_,m,u,k){const a=s("Badge");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"metrics-for-prometheus-and-grafana",tabindex:"-1"},[d("Metrics for Prometheus and Grafana "),t("a",{class:"header-anchor",href:"#metrics-for-prometheus-and-grafana","aria-label":'Permalink to "Metrics for Prometheus and Grafana"'},"​")],-1)),i(a,{type:"built",text:"Built"}),e[1]||(e[1]=c(` Octryx AI serves Prometheus metrics at <code>/metrics</code>, counted in the process at the moment something happens. Metrics never come from database queries.<p>This page is about Octryx AI&#39;s own metrics. For agents reading your Grafana, Prometheus and Loki, see <a href="/docs/connections/monitoring">Grafana, Prometheus and Loki</a>.</p><h2 id="the-metrics" tabindex="-1">The metrics <a class="header-anchor" href="#the-metrics" aria-label="Permalink to &quot;The metrics&quot;">​</a></h2><p>The agent metrics are called <code>octryx_*</code>:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Content</th></tr></thead><tbody><tr><td><code>octryx_llm_requests_total</code>, <code>octryx_llm_request_duration_seconds</code></td><td>LLM requests and duration per provider and model, outcome <code>ok</code>, <code>error</code>, <code>timeout</code>, <code>cancelled</code></td></tr><tr><td><code>octryx_llm_tokens_total</code>, <code>octryx_llm_cost_usd_total</code></td><td>tokens (input, output, cache_read, cache_write) and cost per model</td></tr><tr><td><code>octryx_agent_turns_total</code></td><td>agent turns per agent (agent, workflow or client) and outcome</td></tr><tr><td><code>octryx_agent_sessions_started_total</code>, <code>octryx_agent_sessions</code></td><td>sessions started (main agent or sub-agent), open sessions per status</td></tr><tr><td><code>octryx_tool_calls_total</code>, <code>octryx_tool_call_duration_seconds</code></td><td>tool calls per tool and status, duration</td></tr><tr><td><code>octryx_workflow_runs_started_total</code>, <code>octryx_workflow_runs_finished_total</code>, <code>octryx_workflow_run_duration_seconds</code>, <code>octryx_workflow_runs</code></td><td>workflow runs per workflow and Workspace (by name), duration, open runs</td></tr><tr><td><code>octryx_approvals_requested_total</code>, <code>octryx_approvals_decided_total</code>, <code>octryx_approval_wait_seconds</code>, <code>octryx_approvals_pending</code></td><td>approvals: requested, decided, wait time, pending</td></tr></tbody></table><p>What is committed is counted. The counters live in the process and start at 0 after a restart, which <code>rate()</code> and <code>increase()</code> handle correctly. No label contains a run, session or user id. A metric keeps at most 500 label combinations; more count under <code>other</code>.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><p>Prometheus presents a token as a bearer token: the key <code>METRICS_SCRAPE_TOKEN</code> in the Secret, e.g. <code>--from-literal=METRICS_SCRAPE_TOKEN=&quot;$(openssl rand -hex 32)&quot;</code>. Without a token, only a signed-in user can read <code>/metrics</code>.</p><h2 id="internal-listener-private-network-only" tabindex="-1">Internal listener (private network only) <a class="header-anchor" href="#internal-listener-private-network-only" aria-label="Permalink to &quot;Internal listener (private network only)&quot;">​</a></h2><p>With <code>OCTRYX_METRICS_PORT</code> set, the api and the worker each also serve <code>/metrics</code> on that port without any credential, for a Prometheus in the same private network (a local compose stack). Open that port only to the private network and never publish it (compose: no <code>ports:</code> entry). If the api and the worker share a network namespace, give them different ports. With several api processes (<code>OCTRYX_API_WORKERS</code> &gt; 1) the api listener stays off. Unset (the default), nothing changes.</p><h2 id="scrape" tabindex="-1">Scrape <a class="header-anchor" href="#scrape" aria-label="Permalink to &quot;Scrape&quot;">​</a></h2><p>With the Prometheus Operator, in <code>my-values.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  serviceMonitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    labels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kube-prometheus-stack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the labels your Prometheus selects ServiceMonitors by</span></span></code></pre></div><p>If a separate worker process runs (<code>python -m app.worker_main</code>), it serves its counters on its health port (<code>OCTRYX_WORKER_HEALTH_PORT</code>, default 8001) at <code>/metrics</code>, with the same token. Prometheus then scrapes both. The gauges (<code>octryx_agent_sessions</code>, <code>octryx_workflow_runs</code>, <code>octryx_approvals_pending</code>) come from the api only, so a <code>sum()</code> over both stays right.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>Import <code>deployment/grafana/octryx-agents.json</code> in Grafana (Dashboards → Import) and choose the Prometheus data source. It shows overview, LLM, agents, tools, workflow runs and approvals, with filters for model and Workspace.</p>`,18))])}const f=o(l,[["render",h]]);export{g as __pageData,f as default};
